const body = $json.body || $json;
const anomaly = body.anomaly || {};
const context = body.context || {};
const callback = body.callback || {};
if (body.protocolVersion !== 2 || !context.runId || !context.countryCode || !Number.isInteger(Number(context.anomalyIndex))) throw new Error('缺少 protocolVersion=2、runId、countryCode 或 anomalyIndex');
if (!callback.url || !callback.token) throw new Error('缺少平台回调地址或回调令牌');
return [{ json: { jobId: `mba-${Date.now()}-${Math.random().toString(16).slice(2)}`, anomaly, context, callback, requestedMode: body.requestedMode || 'evidence' } }];

const { anomaly, context } = $json;
const current = String(anomaly.message || '');
const tableHints = [...current.matchAll(/\b(?:ods|dwd|dws|dwb|ads|dim)_[a-z0-9_]+\b/gi)].map((m) => m[0]);
return [{ json: { ...$json, evidencePlan: { maxDepth: 2, maxQueries: 8, checks: ['latest_partition', 'daily_row_count', 'metric_reaggregation', 'ds_status'], tableHints } } }];

const base = $item(0).$node['Build Guarded Evidence Plan'].json;
const sr = $json || {};
const success = sr.success === true || sr.ok === true;
const analysis = { summary: success ? '已完成数据侧连接与基础取证；请根据 Metabase SQL、分区和 DS 证据进一步判定。' : 'SR Box 取证失败，无法据此压制原始告警。', possibleCauses: success ? ['待补充 Metabase Card 原始 SQL 与表级核查结果。'] : ['SR Box 服务账号权限、网络或网关不可用。'], verificationSteps: ['核查目标表最新分区、异常日与前一日行数。', '核查对应 DS 工作流最近执行状态。'], recommendedActions: ['保留原始巡检告警；仅在证据完整后调整通知等级。'], confidence: success ? 'low' : 'low', limitations: success ? '模板仅完成连通性探测；导入后需配置 Metabase Card 读取、表级 SQL 模板和代码血缘节点。' : String(sr.message || sr.error || 'SR Box 无有效返回').slice(0, 500), dataSideVerdict: 'insufficient_evidence', notificationAction: 'enrich_only' };
return [{ json: { ...base, completion: { jobId: base.jobId, runId: base.context.runId, countryCode: base.context.countryCode, anomalyIndex: Number(base.context.anomalyIndex), model: 'n8n-evidence-template', analysis, evidence: { srConnectivity: success, evidencePlan: base.evidencePlan } } }];
